# Compatibility alias for callers that use the shorter name.
PANTHEON_GODS = PANTHEON

DOMAINS = sorted({god["domain"] for god in PANTHEON})


def find_by_domain(domain: str) -> list[dict[str, str]]:
    """Return symbolic entries whose domain matches a case-insensitive query."""
    query = domain.strip().casefold()
    return [god for god in PANTHEON if query in god["domain"].casefold()]


def find_by_name(name: str) -> list[dict[str, str]]:
    query = name.strip().casefold()
    return [god for god in PANTHEON if query in god["name"].casefold()]
